if (!customElements.get('shihiko-localization-modal')) {
  class ShihikoLocalizationModal extends HTMLElement {
    connectedCallback() {
      this.abortController = new AbortController();
      this.initialized = false;
      this.initialize();
    }

    initialize() {
      if (this.initialized) return true;

      this.dialog = this.querySelector('#localization-modal') || this.querySelector('dialog');
      this.form = this.querySelector('#localization-modal-form') || this.querySelector('form');
      this.countryInput = this.querySelector('[data-localization-country-input]');
      this.languageInput = this.querySelector('[data-localization-language-input]');
      this.countryName = this.querySelector('[data-localization-country-name]');
      this.countryCurrency = this.querySelector('[data-localization-country-currency]');
      this.description = this.querySelector('#localization-modal-description');
      this.submitButton = this.querySelector('[data-localization-submit]');
      this.summaryView = this.querySelector('[data-localization-view="summary"]');
      this.countryPicker = this.querySelector('[data-localization-country-picker]');
      this.countryTrigger = this.querySelector('[data-localization-country-open]');
      this.countryDropdown = this.querySelector('[data-localization-country-dropdown]');
      this.countryOptions = [...this.querySelectorAll('[data-localization-country-option]')];
      this.countryGroups = [...this.querySelectorAll('[data-localization-country-group]')];
      this.languageOptions = [...this.querySelectorAll('[data-localization-language-option]')];
      this.countrySearch = this.querySelector('[data-localization-country-search]');
      this.defaultCountryCode = this.dataset.defaultCountryCode || this.countryInput?.value || '';
      this.defaultLanguageCode = this.dataset.defaultLanguageCode || this.languageInput?.value || '';
      this.lastTrigger = null;
      this.pendingCountry = this.defaultCountryCode;
      this.pendingLanguage = this.defaultLanguageCode;
      this.submitting = false;

      if (!this.dialog || !this.form) return false;

      const signal = this.abortController.signal;

      this.dialog.addEventListener('click', (event) => this.onDialogClick(event), { signal });
      this.dialog.addEventListener('cancel', (event) => {
        event.preventDefault();
        this.close();
      }, { signal });
      this.form.addEventListener('submit', (event) => this.onSubmit(event), { signal });
      this.querySelector('[data-localization-close]')?.addEventListener('click', () => this.close(), { signal });
      this.countryTrigger?.addEventListener('click', () => this.toggleCountryDropdown(), { signal });
      this.countryOptions.forEach((option) => {
        option.addEventListener('click', () => this.selectCountry(option), { signal });
      });
      this.languageOptions.forEach((option) => {
        option.addEventListener('change', () => this.selectLanguage(option), { signal });
      });
      this.countrySearch?.addEventListener('input', (event) => this.filterCountries(event.target.value), { signal });
      this.syncLanguageOptions();
      this.initialized = true;
      return true;
    }

    disconnectedCallback() {
      this.abortController?.abort();
      this.initialized = false;
    }

    onDialogClick(event) {
      if (event.target === this.dialog) {
        this.close();
        return;
      }

      if (this.countryDropdown && !this.countryDropdown.hasAttribute('hidden') && !this.countryPicker?.contains(event.target)) {
        this.closeCountryDropdown();
      }
    }

    onSubmit(event) {
      if (this.submitting) {
        event.preventDefault();
        return;
      }

      this.submitting = true;
      this.submitButton?.setAttribute('disabled', 'disabled');
      this.dialog?.setAttribute('data-submitting', 'true');
    }

    open(trigger) {
      if (!this.initialize()) return;

      this.lastTrigger = trigger;
      this.resetPendingState();
      this.showSummaryView(false);
      this.submitting = false;
      this.submitButton?.removeAttribute('disabled');
      this.dialog.removeAttribute('data-submitting');
      this.setTriggerState(true, trigger);

      if (!this.dialog.open) {
        this.dialog.showModal();
      }

      this.syncScrollLock();
      window.requestAnimationFrame(() => this.querySelector('[data-localization-close]')?.focus());
    }

    close() {
      if (this.dialog?.open) this.dialog.close();
      this.showSummaryView(false);
      this.setTriggerState(false);
      this.syncScrollLock();
      this.lastTrigger?.focus();
      this.lastTrigger = null;
    }

    syncScrollLock() {
      const mobileMenuOpen = Boolean(document.querySelector('.header-new__mobile-menu.open'));
      const cartOpen = Boolean(document.querySelector('#cart-popup.open, .cart-popup-overflow.open'));
      const localizationOpen = Boolean(this.dialog?.open);
      document.body.classList.toggle('disable-scroll', Boolean(mobileMenuOpen || cartOpen || localizationOpen));
    }

    resetPendingState() {
      this.pendingCountry = this.defaultCountryCode;
      this.pendingLanguage = this.defaultLanguageCode;
      if (this.countryInput) this.countryInput.value = this.pendingCountry;
      if (this.languageInput) this.languageInput.value = this.pendingLanguage;
      this.syncCountryOptions();
      this.syncLanguageOptions();
      this.updateCountrySummary(this.findCountryOption(this.pendingCountry));
      this.closeCountryDropdown();
      if (this.countrySearch) {
        this.countrySearch.value = '';
        this.filterCountries('');
      }
    }

    showSummaryView(focus = true) {
      this.closeCountryDropdown();
      if (focus) {
        window.requestAnimationFrame(() => this.dialog?.querySelector('[data-localization-country-open]')?.focus());
      }
    }

    toggleCountryDropdown() {
      if (!this.countryDropdown) return;

      if (this.countryDropdown.hasAttribute('hidden')) {
        this.countryDropdown.removeAttribute('hidden');
        this.countryTrigger?.setAttribute('aria-expanded', 'true');
        window.requestAnimationFrame(() => this.countrySearch?.focus() || this.countryOptions[0]?.focus());
        return;
      }

      this.closeCountryDropdown();
    }

    closeCountryDropdown() {
      this.countryDropdown?.setAttribute('hidden', 'hidden');
      this.countryTrigger?.setAttribute('aria-expanded', 'false');
    }

    selectCountry(option) {
      this.pendingCountry = option.dataset.countryCode || '';
      if (this.countryInput) this.countryInput.value = this.pendingCountry;
      this.syncCountryOptions();
      this.updateCountrySummary(option);
      this.showSummaryView();
    }

    selectLanguage(option) {
      this.pendingLanguage = option.value;
      if (this.languageInput) this.languageInput.value = this.pendingLanguage;
    }

    syncCountryOptions() {
      this.countryOptions.forEach((option) => {
        option.setAttribute('aria-selected', option.dataset.countryCode === this.pendingCountry ? 'true' : 'false');
      });
    }

    syncLanguageOptions() {
      this.languageOptions.forEach((option) => {
        option.checked = option.value === this.pendingLanguage;
      });
    }

    updateCountrySummary(option) {
      if (!option) return;

      const countryName = option.dataset.countryName || '';
      const currencyCode = option.dataset.currencyCode || '';
      const currencySymbol = option.dataset.currencySymbol || '';

      if (this.countryName) this.countryName.textContent = countryName;
      if (this.countryCurrency) this.countryCurrency.textContent = `${currencyCode} ${currencySymbol}`.trim();
      if (this.description) {
        const descriptionTemplate = this.description.dataset.template;
        if (descriptionTemplate) {
          this.description.textContent = descriptionTemplate
            .replace('[country]', countryName)
            .replace('[currency]', currencyCode)
            .replace('[symbol]', currencySymbol);
        }
      }
    }

    findCountryOption(countryCode) {
      return this.countryOptions.find((option) => option.dataset.countryCode === countryCode);
    }

    setTriggerState(open, activeTrigger = null) {
      document.querySelectorAll('[data-localization-modal-open]').forEach((trigger) => {
        trigger.setAttribute('aria-expanded', open && trigger === activeTrigger ? 'true' : 'false');
      });
    }

    filterCountries(value) {
      const query = value.trim().toLowerCase();
      this.countryOptions.forEach((option) => {
        const searchable = `${option.dataset.countryName || ''} ${option.dataset.countryCode || ''}`.toLowerCase();
        option.hidden = Boolean(query && !searchable.includes(query));
      });

      this.countryGroups.forEach((group) => {
        const hasVisibleOption = group.querySelector('[data-localization-country-option]:not([hidden])');
        group.hidden = !hasVisibleOption;
      });
    }
  }

  customElements.define('shihiko-localization-modal', ShihikoLocalizationModal);

  document.addEventListener('click', (event) => {
    if (!(event.target instanceof Element)) return;

    const trigger = event.target.closest('[data-localization-modal-open]');
    const modal = document.querySelector('shihiko-localization-modal');
    if (!trigger || typeof modal?.open !== 'function') return;

    event.preventDefault();
    modal.open(trigger);
  });
}
